#include HEADER
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <numeric>
using Clock=std::chrono::steady_clock;
[[gnu::noipa]]std::uint64_t count(const PrimeSieve&s){return s.prime_count();}
[[gnu::noipa]]std::uint64_t primes(const PrimeSieve&s){auto x=s.primes();return x.size()+(x.empty()?0:x.back());}
[[gnu::noipa]]std::uint64_t each(const PrimeSieve&s){std::uint64_t sum=0;s.for_each_prime([&sum](auto p){sum+=p;});return sum;}
[[gnu::noipa]]std::uint64_t build(std::uint64_t n){PrimeSieve s(n);return count(s);}
int main(int argc,char**argv){
 std::uint64_t n=std::strtoull(argv[1],nullptr,10);int mode=std::atoi(argv[2]);auto reps=std::strtoul(argv[3],nullptr,10);PrimeSieve s(n);std::uint64_t sum=0;
 auto begin=Clock::now();
 for(unsigned i=0;i<reps;++i){if(mode==0)sum+=build(n);else if(mode==1)sum+=count(s);else if(mode==2)sum+=primes(s);else sum+=each(s);}
 auto ns=std::chrono::duration<double,std::nano>(Clock::now()-begin).count()/reps;std::printf("%.9g %ju\n",ns,std::uintmax_t(sum));}

