for n in sorted({x['n']for x in rows}):
 for mode in ['default','native']:
  for op in range(4):
   rr=[x for x in rows if x['n']==n and x['mode']==mode and x['op']==op];assert len({x['checksum']for x in rr})==1
   med={v:st.median(x['ns']for x in rr if x['variant']==v)for v in ['baseline','control',*variants[1:]]};summary.append(dict(n=n,mode=mode,op=op,median_ns=med,ratio={v:t/med['baseline']for v,t in med.items()}))
(p/'base-lut-results.json').write_text(json.dumps(dict(builds=builds,raw=rows,summary=summary),indent=2));print(json.dumps(summary,indent=2))

