#include HEADER
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <vector>
using Clock=std::chrono::steady_clock;
[[gnu::noipa]]void external(std::uint64_t&sum,std::uint64_t p){sum+=p^(p>>7);}
[[gnu::noipa]]std::uint64_t run(const PrimeSieve&s,int mode){
 std::uint64_t sum=0;std::vector<std::uint64_t>v;
 if(mode==0)s.for_each_prime([&sum](auto){++sum;});
 else if(mode==1){v.reserve(s.prime_count());s.for_each_prime([&v](auto p){v.push_back(p);});sum=v.size()+(v.empty()?0:v.back());}
 else if(mode==2){s.for_each_prime([&v](auto p){v.push_back(p);});sum=v.size()+(v.empty()?0:v.back());}
 else if(mode==3)s.for_each_prime([&sum](auto p){external(sum,p);});
 else if(mode==4)s.for_each_prime([&sum](auto p){if((p&7)==1)sum+=p;});
 else s.for_each_prime([&sum](auto p){sum+=p;});
 return sum;
}
int main(int argc,char**argv){std::uint64_t n=std::strtoull(argv[1],nullptr,10);int mode=std::atoi(argv[2]);auto reps=std::strtoul(argv[3],nullptr,10);PrimeSieve s(n);std::uint64_t sum=0;auto begin=Clock::now();for(unsigned i=0;i<reps;++i)sum+=run(s,mode);auto ns=std::chrono::duration<double,std::nano>(Clock::now()-begin).count()/reps;std::printf("%.9g %ju\n",ns,std::uintmax_t(sum));}

