from pathlib import Path
import subprocess as sp,json,statistics as st,random,fcntl,hashlib
p=Path(__file__).parent;variants=['baseline','foreach_two','foreach_bmi'];builds=[];rows=[];rng=random.Random(413720)
for flags,mode in [([], 'default'),(['-march=native'],'native')]:
 for v in variants:
  cmd=['taskset','-c','8','/usr/bin/g++','-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS',*flags,'-DHEADER="'+str(p/(v+'.hpp'))+'"',str(p/'api.cpp'),'-o',str(p/(mode+'_'+v))];q=sp.run(cmd,capture_output=True,text=True);assert q.returncode==0,q.stderr;builds.append(dict(cmd=cmd,diagnostics=q.stderr,sha256=hashlib.sha256((p/(v+'.hpp')).read_bytes()).hexdigest()))
with open('/tmp/sirkit_performance_cpu4.lock','a')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for n in [1000,100000,1000000,10000000,100000000]:
  for mode in ['default','native']:
   for op in range(4):
    reps=max(2,min(1000,2000000//n))
    for rep in range(7):
     vs=['baseline','control',*variants[1:]];rng.shuffle(vs)
     for v in vs:
      q=sp.run(['taskset','-c','4',str(p/(mode+'_'+('baseline'if v=='control'else v))),str(n),str(op),str(reps)],capture_output=True,text=True);assert q.returncode==0,q.stderr;ns,check=q.stdout.split();rows.append(dict(n=n,mode=mode,op=op,rep=rep,variant=v,ns=float(ns),checksum=check))
  print(n,flush=True)
summary=[]
for n in sorted({x['n']for x in rows}):
 for mode in ['default','native']:
  for op in range(4):
   rr=[x for x in rows if x['n']==n and x['mode']==mode and x['op']==op];assert len({x['checksum']for x in rr})==1
   med={v:st.median(x['ns']for x in rr if x['variant']==v)for v in ['baseline','control',*variants[1:]]};summary.append(dict(n=n,mode=mode,op=op,median_ns=med,ratio={v:t/med['baseline']for v,t in med.items()}))
(p/'foreach-bmi-results.json').write_text(json.dumps(dict(builds=builds,raw=rows,summary=summary),indent=2));print(json.dumps(summary,indent=2))

