from pathlib import Path
import re,subprocess as sp,json,hashlib
p=Path(__file__).parent;rows=[]
def funcs(exe):
 s=sp.check_output(['objdump','-d','-C',str(exe)],text=True);parts=re.split(r'(?m)^([0-9a-f]+) <(.+)>:\n',s);out={}
 for i in range(1,len(parts),3):out[parts[i+1]]=(int(parts[i],16),parts[i+2].split('\n\n')[0])
 return out
for mode in ['default','native']:
 for aligned in [False,True]:
  prefix='aligned_'if aligned else'';exes={v:p/(prefix+mode+'_'+v)for v in ['baseline','final']}
  if not all(exe.exists()for exe in exes.values()):continue
  fs={v:funcs(exe)for v,exe in exes.items()}
  for name in fs['baseline']:
   if not(name=='each(PrimeSieve const&)'or name=='count(PrimeSieve const&)'or'reinsirk::detail::popcount_words_'in name):continue
   if name not in fs['final']:continue
   operands={};assembly={};addresses={}
   for v in ['baseline','final']:
    addr,ss=fs[v][name];addresses[v]=addr;assembly[v]=ss;out=[]
    for line in ss.splitlines():
     cols=line.split('\t')
     if len(cols)<3:continue
     instr=cols[-1].strip();instr=re.sub(r'\b[0-9a-f]+ <'+re.escape(name)+r'\+0x([0-9a-f]+)>',r'LOCAL+\1',instr);instr=re.sub(r'\b[0-9a-f]+ <([^>]+)>',r'TARGET<\1>',instr);instr=re.sub(r'-?0x[0-9a-f]+\(%rip\)',r'TABLE(%rip)',instr);instr=re.sub(r'#.*','',instr).strip();out.append(instr)
    operands[v]=out
   rows.append(dict(mode=mode,aligned_wrapper=aligned,function=name,start_addresses=addresses,normalized_instructions_equal=operands['baseline']==operands['final'],normalized_instructions=operands,raw_assembly=assembly))
(p/'instruction-proof.json').write_text(json.dumps(rows,indent=2)+'\n');print([(x['mode'],x['aligned_wrapper'],x['function'],x['normalized_instructions_equal'])for x in rows])

