p=Path(__file__).parent;variants=['baseline','mask37','mask47','mask61','mask97','mask127'];commands=[];rows=[];checks={};rng=random.Random(413720)
for mode,flags in [('native',['-march=native']),('plain',[])]:
 for v in variants:
  exe=p/(mode+'_'+v);cmd=['taskset','-c','6','/usr/bin/g++','-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS',*flags,'-DHEADER="'+str(p/(v+'.hpp'))+'"',str(p/'bench.cpp'),'-o',str(exe)];q=sp.run(cmd,capture_output=True,text=True);assert q.returncode==0,q.stderr;commands.append(dict(mode=mode,variant=v,cmd=cmd,source_sha256=hashlib.sha256((p/(v+'.hpp')).read_bytes()).hexdigest(),binary_sha256=hashlib.sha256(exe.read_bytes()).hexdigest(),stderr=q.stderr))
with open('/tmp/sirkit_performance_cpu12.lock','a')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for n in [100000,1000000,10000000,100000000,500000000]:
  for mode in ['native','plain']:
   for rep in range(5):
    vs=variants+['control'];rng.shuffle(vs)
    for v in vs:
     exe=p/(mode+'_'+('baseline'if v=='control'else v));q=sp.run(['taskset','-c','12',str(exe),str(n),'0',str(max(1,10000000//n))],capture_output=True,text=True);assert q.returncode==0,q.stderr;t,c=q.stdout.split();assert n not in checks or checks[n]==c,(n,v,c,checks[n]);checks[n]=c;rows.append(dict(mode=mode,n=n,rep=rep,variant=v,ns=float(t),checksum=c))
   (p/'probe-raw.json').write_text(json.dumps(dict(commands=commands,raw=rows),indent=2));print(n,mode,flush=True)
summary={}
for mode in ['native','plain']:
 summary[mode]={}
 for n in checks:
  med={v:st.median(x['ns']for x in rows if x['mode']==mode and x['n']==n and x['variant']==v)for v in variants+['control']};summary[mode][n]={'baseline_ns':med['baseline'],**{v:t/med['baseline']for v,t in med.items()}};print(mode,n,summary[mode][n],flush=True)
(p/'probe-summary.json').write_text(json.dumps(summary,indent=2))

